contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= depositAmount);

        c.depositsCount(); if (__ESBMC_reverted()) return;

        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balanceAfter = address(c).balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            reverted == (value > balanceBefore) &&
            (reverted
                ? (balanceAfter == balanceBefore && depositsAfter == depositsBefore)
                : (balanceBefore - balanceAfter == value && depositsAfter == depositsBefore)
            )
        );
    }

    receive() external payable {}
}

