pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 depositAmount, uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.depositsCount() {} catch { return; }
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balanceAfter = address(c).balance;
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        assertTrue(reverted == (value > balanceBefore) &&
            (reverted
                ? (balanceAfter == balanceBefore && depositsAfter == depositsBefore)
                : (balanceBefore - balanceAfter == value && depositsAfter == depositsBefore)
            ));
    }

    function testFuzz_run(uint256 depositAmount, uint256 value) public {
        _run(depositAmount, value);
    }

    receive() external payable {}
}
